    <header class="pharmacy-page-header"><div><div class="pharmacy-eyebrow">Pharmacy operations</div><h1 class="pharmacy-page-title" id="pharmacy-dashboard-title">Pharmacy Dashboard</h1><p class="pharmacy-page-description">A focused view of prescriptions, stock, orders, payments, and deliveries for this clinic.</p><p class="pharmacy-dashboard-date"><i class="bi bi-calendar3 mr-1" aria-hidden="true"></i><?= esc(date('d M Y')) ?></p></div><button class="btn btn-primary" type="button" id="pharmacyDashboardRefresh"><i class="bi bi-arrow-clockwise mr-1" aria-hidden="true"></i>Refresh</button></header>
